function ok(data, text) {
    return {
        content: [{ type: "text", text: text ?? JSON.stringify(data, null, 2) }],
        structuredContent: data,
    };
}
function err(message) {
    return { content: [{ type: "text", text: `Error: ${message}` }] };
}
